<template><admin-layout><admin-review-panel><h1>{{ $t('Refunds') }}</h1><div class="review-grid"><div v-for="state in ['pending','processing','completed','failed']" :key="state"><span>{{ $t(state) }}</span><p>{{ stats[state+'_count'] }} · {{ stats[state+'_amount'] }} USD</p></div></div><form @submit.prevent="filter"><label>{{ $t('Merchant') }} <themed-select v-model="local.merchant_id"><option value="">{{ $t('All') }}</option><option v-for="m in merchants" :key="m.id" :value="m.id">{{ m.business_name }}</option></themed-select></label><label>{{ $t('Status') }} <themed-select v-model="local.status"><option value="">{{ $t('All') }}</option><option v-for="s in ['pending','processing','completed','failed','cancelled']" :key="s" :value="s">{{ $t(s) }}</option></themed-select></label><button>{{ $t('Filter') }}</button></form><div class="review-scroll"><table><thead><tr><th>ID</th><th>{{ $t('Merchant') }}</th><th>{{ $t('Amount') }}</th><th>{{ $t('Status') }}</th><th>{{ $t('Date') }}</th></tr></thead><tbody><tr v-for="row in refunds.data" :key="row.id"><td><a :href="route('admin.merchant.refunds.show',row.id)">{{ row.id }}</a></td><td>{{ row.merchant ? row.merchant.business_name : '—' }}</td><td>{{ row.amount_crypto }}<br>{{ row.amount_usd }} USD</td><td>{{ $t(row.status) }}</td><td>{{ row.created_at }}</td></tr><tr v-if="!refunds.data.length"><td colspan="5">{{ $t('No records') }}</td></tr></tbody></table></div><pagination :links="refunds.links"/></admin-review-panel></admin-layout></template>
<script>
import AdminLayout from '@/Layouts/AdminLayout';import AdminReviewPanel from '@/Components/AdminReviewPanel';import Pagination from '@/Jetstream/Pagination';
export default {components:{AdminLayout,AdminReviewPanel,Pagination},props:{refunds:Object,stats:Object,merchants:Array,filters:Object},data(){return{local:{merchant_id:this.filters.merchant_id||'',status:this.filters.status||''}}},methods:{filter(){this.$inertia.get(this.route('admin.merchant.refunds'),this.local,{preserveState:true})}}};
</script>
